import os
import torch


class Config:
    """
    Configuration class for the Hybrid Transformer-MLP solution.
    Centralizes paths, hyperparameters, and global settings.
    """

    # ==========================================
    # File Paths & Directories
    # ==========================================
    # Input Metadata Paths (Generated by metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working Directory for Caching (Idea 3 specific)
    WORKING_DIR = "./working/idea_3"

    # Output Directory for Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Processing Configuration
    # ==========================================
    ID_COL = "id"
    TARGET_COL = "target"
    SEQ_COL = "f_27"

    # Sequence Tokenization
    # 26 Uppercase letters + 1 Padding + 1 Unknown = 28
    VOCAB_SIZE = 28
    MAX_SEQ_LEN = 10  # The string length is fixed at 10 for this dataset

    # Caching
    LOAD_CACHED_DATA = True  # Set to False to force re-processing

    # Debugging
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 10000  # Number of rows to use if DEBUG is True

    # ==========================================
    # Model Architecture: Hybrid Transformer-MLP
    # ==========================================
    # Sequence Branch (Transformer)
    EMBED_DIM = 64
    N_HEADS = 4
    N_TRANSFORMER_LAYERS = 2
    DIM_FEEDFORWARD = 256
    TRANSFORMER_DROPOUT = 0.1

    # Numerical Branch & Fusion Head
    # The numerical features are concatenated with the pooled transformer output
    # and passed through this MLP.
    MLP_HIDDEN_SIZES = [1024, 512, 256]
    MLP_DROPOUT = 0.1

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    BATCH_SIZE = 1024
    EPOCHS = 30
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2  # For AdamW

    # Optimization
    EARLY_STOPPING_PATIENCE = 5
    SCHEDULER_WARMUP_PCT = 0.1

    # ==========================================
    # Compute & Environment
    # ==========================================
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Initialize directories and set random seeds for reproducibility.
        """
        # Ensure directories exist
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set seeds
        torch.manual_seed(cls.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(cls.SEED)
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
